package com.cartalaap.garage;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.Table;
@Entity@Table(name="garage_vehicle_images")public class GarageVehicleImage{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="vehicle_id")private GarageVehicle vehicle;@Column(name="image_url")private String imageUrl;@Column(name="sort_order")private int sortOrder;protected GarageVehicleImage(){}public GarageVehicleImage(GarageVehicle vehicle,String imageUrl,int sortOrder){this.vehicle=vehicle;this.imageUrl=imageUrl;this.sortOrder=sortOrder;}public String getImageUrl(){return imageUrl;}}
